good.code:
const RETRYABLE = new Set([408, 429, 502, 503, 504])

async function call(req: Req, deadline: number, maxAttempts = 3) {
  for (let attempt = 0; ; attempt++) {
    const res = await http(req, { timeoutMs: deadline - Date.now() }).catch(err => err)
    const retryable = res instanceof NetworkError || RETRYABLE.has(res.status)
    if (!retryable || attempt + 1 >= maxAttempts) return res
    if (!req.idempotent && !req.idempotencyKey) return res
    if (!retryBudget.tryTake()) return res
    const ceiling = Math.min(5000, 100 * 2 ** attempt)
    const advised = retryAfterMs(res) ?? 0
    const wait = Math.max(advised, Math.random() * ceiling) // full jitter
    if (Date.now() + wait >= deadline) return res          // no time left: give up
    await sleep(wait)
  }
}

